-- 111 - THE NEW INTERNATIONAL ORDER FORM: THE BASE (owner 8/11, change 13; docs/design/intl-order-form-2026-11-08.md,
-- section 4: the three answers). Generated by drafts/tools/build-111.mjs - never hand-edited.
-- The owner runs it in the Supabase SQL editor AFTER 15:00, with an explicit yes, one step at a time:
--   1. 111_intl_form_stops_dryrun.sql   this block + the proofs, then a deliberate error: NOTHING kept
--   2. 111_intl_form_stops.sql          (this file)
--   3. 111_intl_form_stops_verify.sql   read-only, one row
-- THEN the Worker (labels Time From / Time To, Via Hub out of dbOnly), THEN the front end. Never the Worker first: its
-- labels name columns that would not exist, and every save of an order's stops would fail.
-- ASCII only. ONE DO block = ONE statement: an error anywhere undoes all of it.
--
-- WHAT IT CHANGES
--   (a) order_stops.time_from / time_to: text 'HH:MM' (the same CHECK as local_moves, 060), NULL = all day. Optional
--       (owner 8/11: "mi ypoxreotiko"); from > to is a night window and allowed (as the national form, 094).
--   (b) order_stops.via_hub becomes the international desk's choice per stop: NULL = follows the VS (every national-
--       side stop of a VS, the rule of today), true = through Veroia, false = direct. Every stop is decided on its own,
--       so a save that writes its stops one by one never passes through a wrong state. DROP NOT NULL + DROP DEFAULT,
--       and every value of today goes to NULL: none was a choice (the facade refused the label, Q-6) - each was the
--       bridge's echo of its own rule, so the bridges stay exactly as they are (proof: B-95 = 0 after, shipments
--       unchanged). plan_h_bridge_wanted reads it (one definition); plan_bridge_sync no longer writes it; the stop
--       trigger also fires on a change of via_hub. B-95 reads the same rule; B-99 now says a choice on a stop that is
--       not the national side.
--   (c) pl_h_delivery_write (108) follows the stop's pallets_exchanged: 0 = no delivery movement, NULL = every pallet,
--       a whole number 1..pallets = that many, anything else = every pallet with the value in the audit row (the
--       loading feeder's rule, core/pallet-feed.js _plLoadTaken). pl_v_missing_delivery (107) no longer lists a stop
--       with 0 (nothing is missing there). Today 0 of 812 stops have a value: nothing changes until the form writes.
-- RUNTIME: one ALTER TABLE (a short lock on order_stops, lock_timeout 5s), one UPDATE of via_hub on ~1.7k rows (no
-- trigger fires: the stop trigger is recreated after it), four function bodies, one view, two checks.
-- statement_timeout 60s. Triggers: the count does not change (B-54 untouched).
-- REVERSE: 111_intl_form_stops_rollback.sql (old bodies verbatim; via_hub back to the bridge's echo; the hour columns
-- are dropped only while empty).
-- EXPECTED: NOTICE "111 OK: ..." ; then verify: result = '111 in place'.

DO $do$
DECLARE
  v_g record; v_b95 int; v_b99 int; v_true0 int; v_false0 int; v_sh0 int; v_sh1 int; v_trg0 int; v_trg1 int; v_k int;
  v_t0 timestamptz := clock_timestamp();
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  PERFORM set_config('statement_timeout', '60s', true);
  PERFORM set_config('search_path', 'public', true);

  -- ===== PART 0: GUARDS (nothing written before them) =====
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'order_stops' AND column_name IN ('time_from', 'time_to')) THEN
    -- the bridge body tells the two apart: still 074's text = a rollback kept the hours; anything else = 111 ran
    IF (SELECT md5(prosrc) FROM pg_proc WHERE oid = to_regprocedure('public.plan_h_bridge_wanted(bigint)')) = 'b53c50f4398f90c43bf9912b41a94271' THEN
      RAISE EXCEPTION '111: order_stops.time_from / time_to exist while the bridge is 074''s - a rollback kept the hours: copy them, drop the two columns and their CHECKs, then run 111 again';
    END IF;
    RAISE EXCEPTION '111: order_stops.time_from / time_to already exist - 111 has run, nothing to do';
  END IF;
  -- the LIVE texts 111 replaces, as 074 / 107 / 108 left them (md5 measured on production 8/11 by SELECT): a body
  -- changed since is not overwritten blind
  FOR v_g IN SELECT * FROM (VALUES
      ('public.plan_h_bridge_wanted(bigint)', 'b53c50f4398f90c43bf9912b41a94271'),
      ('public.plan_bridge_sync(bigint,text)', '3a94d6925b43dec17e26da59447d517c'),
      ('public.plan_bridge_on_stop()', 'c133ef3f4928da5a625af58072e5af32'),
      ('public.pl_h_delivery_write(bigint,bigint,text)', '51c77086b10c4db8f04f1747199cad5a')) g(sig, h) LOOP
    IF to_regprocedure(v_g.sig) IS NULL OR (SELECT md5(prosrc) FROM pg_proc WHERE oid = to_regprocedure(v_g.sig)) <> v_g.h THEN
      RAISE EXCEPTION '111: % is not the text 111 was written against - stop, re-measure', v_g.sig;
    END IF;
  END LOOP;
  IF md5(pg_get_viewdef('public.pl_v_missing_delivery'::regclass, true)) <> '6f8cc4d6b045a8679dd63a7bfe3cec6e' THEN
    RAISE EXCEPTION '111: pl_v_missing_delivery is not 107''s text (md5 %) - stop', md5(pg_get_viewdef('public.pl_v_missing_delivery'::regclass, true));
  END IF;
  IF (SELECT count(*) FROM monitoring.checks WHERE (id = 'B-95' AND md5(sql_text) = 'f255e0226bc9378644f86bcb533d4a69' AND md5(ids_sql) = '70eb6d174a4ab69dd3f5bb4127cc9b52')
                                              OR (id = 'B-99' AND md5(sql_text) = 'df11dab3bee7650c32d3cc41070ec4d6' AND md5(ids_sql) = '54aac1f418680ee5bc1136c92c247852')) <> 2 THEN
    RAISE EXCEPTION '111: B-95 / B-99 are not 074b''s text - stop, re-measure';
  END IF;
  -- the bridge must be whole before: a gap already there is not 111's, and the proof after must not hide it
  EXECUTE (SELECT sql_text FROM monitoring.checks WHERE id = 'B-95') INTO v_b95;
  IF v_b95 <> 0 THEN RAISE EXCEPTION '111: B-95 is red before 111 (% orders) - stop, ask', v_b95; END IF;
  SELECT count(*) FILTER (WHERE via_hub), count(*) FILTER (WHERE NOT via_hub) INTO v_true0, v_false0 FROM public.order_stops;
  SELECT count(*) INTO v_sh0 FROM public.shipments WHERE deleted_at IS NULL;
  SELECT count(*) INTO v_trg0 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace ns ON ns.oid = c.relnamespace
   WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';

  -- ===== PART 1 (a): THE HOURS =====
  ALTER TABLE public.order_stops
    ADD COLUMN time_from text, ADD COLUMN time_to text,
    ADD CONSTRAINT order_stops_time_from_fmt CHECK (time_from IS NULL OR time_from ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
    ADD CONSTRAINT order_stops_time_to_fmt CHECK (time_to IS NULL OR time_to ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
    ALTER COLUMN via_hub DROP NOT NULL, ALTER COLUMN via_hub DROP DEFAULT;
  COMMENT ON COLUMN public.order_stops.time_from IS 'HH:MM, optional (owner 8/11): NULL = from the start of the day (111)';
  COMMENT ON COLUMN public.order_stops.time_to IS 'HH:MM, optional (owner 8/11): NULL = to the end of the day; from > to = a night window (111)';

  -- ===== PART 2 (b): VIA HUB = THE DESK'S CHOICE =====
  COMMENT ON COLUMN public.order_stops.via_hub IS 'The international desk''s choice per stop (111): NULL = follows the VS, true = through Veroia, false = direct';
  -- the bridge's echo goes; the old stop trigger does not fire on via_hub, so nothing is synced by this UPDATE
  UPDATE public.order_stops SET via_hub = NULL WHERE via_hub IS NOT NULL;
  GET DIAGNOSTICS v_k = ROW_COUNT;
  IF v_k <> v_true0 + v_false0 THEN RAISE EXCEPTION '111: via_hub reset % rows, expected %', v_k, v_true0 + v_false0; END IF;
  CREATE OR REPLACE FUNCTION public.plan_h_bridge_wanted(p_stop bigint) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$
  select coalesce((
    -- 111: and the international desk did not take it out of Veroia (via_hub false = direct; NULL = follows the VS)
    select s.deleted_at is null and coalesce(s.pallets, 0) > 0 and s.via_hub is distinct from false
       and plan_h_vs_nat_side(o.direction, s.stop_type)
       and plan_h_vs_in_v5(o.id)
      from order_stops s join orders o on o.id = s.order_id where s.id = p_stop), false)
$f$;
  CREATE OR REPLACE FUNCTION public.plan_bridge_sync(p_order bigint, p_why text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
declare
  v_actor text := coalesce(nullif(btrim(p_why), ''), 'trigger:plan_bridge_sync');
  v_role constant text := 'system';
  st record; v_w boolean; v_sh bigint; v_new int := 0; v_p shipment_pieces%rowtype; v_s shipments%rowtype;
  v_ref text; nl record;
begin
  if plan_cutover_day() is null then return; end if;
  -- a bridge whose stop moved to another order (or lost it) is not this order's any more
  for v_sh in select s.id from shipments s join order_stops os on os.id = s.order_stop_id
               where s.order_id = p_order and s.deleted_at is null and os.order_id is distinct from p_order order by s.id loop
    perform plan_h_bridge_retire(v_sh, v_actor, v_actor, v_role);
  end loop;
  for st in select s.id, s.pallets from order_stops s where s.order_id = p_order order by s.id loop
    v_w := plan_h_bridge_wanted(st.id);
    select id into v_sh from shipments where order_stop_id = st.id and deleted_at is null;
    if v_w and v_sh is null then
      insert into shipments (order_id, order_stop_id, created_by) values (p_order, st.id, v_actor) returning * into v_s;
      perform plan_h_audit(v_actor, v_role, 'create', 'shipments', v_s.id::text, null, to_jsonb(v_s));
      insert into shipment_pieces (shipment_id, pallets, created_by) values (v_s.id, st.pallets, v_actor) returning * into v_p;
      perform plan_h_audit(v_actor, v_role, 'create', 'shipment_pieces', v_p.id::text, null, to_jsonb(v_p));
      v_new := v_new + 1;
    elsif not v_w and v_sh is not null then
      perform plan_h_bridge_retire(v_sh, v_actor, v_actor, v_role);
    end if;
    -- 111: via_hub is the international desk's choice, read by plan_h_bridge_wanted and never written here
  end loop;
  if v_new > 0 then
    -- every old Direct NL is unlinked, Delivered ones too (owner 28/10: the old national data has no business value
    -- and never blocks v5 - an old VS moved onto day L or later takes the normal bridge path); its id stays in
    -- plan_cutover_log and the soft delete is audited
    select coalesce(reference, id::text) into v_ref from orders where id = p_order;
    for nl in update national_loads set deleted_at = now()
               where source_order_id = p_order and source_type = 'Direct' and deleted_at is null
               returning id, legacy_id, truck_id, partner_id, status loop
      insert into plan_cutover_log (kind, table_name, row_id, reason, before_data)
      values ('nl_unlinked', 'national_loads', nl.id, v_actor,
              jsonb_build_object('order_id', p_order, 'truck_id', nl.truck_id, 'partner_id', nl.partner_id, 'status', nl.status));
      perform plan_h_audit(v_actor, v_role, 'delete', 'national_loads', coalesce(nl.legacy_id, nl.id::text),
                           jsonb_build_object('deleted_at', null), jsonb_build_object('deleted_at', now(), 'reason', 'v5 bridge (074)'));
      -- Q-3: the desk re-records in v5 every unlinked load that was already moving - a vehicle on it, or a status past
      -- Pending (a Friday export Delivered at Veroia with no truck on the record); a Cancelled load has nothing to re-record
      if nl.status is distinct from 'Cancelled'
         and (nl.truck_id is not null or nl.partner_id is not null or nl.status is distinct from 'Pending') then
        -- "I VS %s perase sto neo board; to palio ethniko fortio eiche ochima (%s): anathese tin xana"
        perform plan_h_notice('natl', 'legacy_nl_replaced',
          'zpcgVlMgJXMgz4DOrc+BzrHPg861IM+Dz4TOvyDOvc6tzr8gYm9hcmTCtyDPhM6/IM+AzrHOu865z4wgzrXOuM69zrnOus+MIM+Gzr/Pgc+Ezq/OvyDOtc6vz4fOtSDPjM+HzrfOvM6xICglcyk6IM6xzr3OrM64zrXPg86tIM+EzrfOvSDOvs6xzr3OrA==',
          array[v_ref, coalesce('truck ' || nl.truck_id, 'partner ' || nl.partner_id, 'status ' || coalesce(nl.status, '-'))],
          p_order, null, null, v_actor, v_role);
      end if;
    end loop;
  end if;
end
$f$;
  CREATE OR REPLACE FUNCTION public.plan_bridge_on_stop() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
declare v_sh bigint; v_o orders%rowtype;
begin
  if plan_cutover_day() is null then return null; end if;
  if new.order_id is null and (tg_op = 'INSERT' or old.order_id is null) then return null; end if;
  -- the common case first, as plan_bridge_on_order: a stop of an order that is not a VS and has no bridge is not the
  -- bridge's (111: via_hub is the desk's choice and wants a VS, so it no longer decides here)
  if (tg_op = 'INSERT' or old.order_id is not distinct from new.order_id)
     and not exists (select 1 from orders o where o.id = new.order_id and o.veroia_switch)
     and not exists (select 1 from shipments s where s.order_id = new.order_id and s.deleted_at is null) then
    return null;
  end if;
  if tg_op = 'UPDATE' then
    select id into v_sh from shipments where order_stop_id = new.id and deleted_at is null;
    -- 111: a write that takes the stop out of Veroia (via_hub to false) retires the bridge in the sync below: no
    -- place / recut / unplan (and no notice) for a load leaving the board. A bridge already kept direct (executed)
    -- still follows its stop.
    if v_sh is not null and new.order_id is not distinct from old.order_id and new.deleted_at is null
       and not (new.via_hub is false and old.via_hub is distinct from false) then
      if old.location_id is distinct from new.location_id and current_setting('plan.writer', true) is distinct from 'natl' then
        perform plan_h_bridge_place(new.id, old.location_id, new.location_id, 'trigger:plan_bridge_sync', 'system');
      end if;
      if old.pallets is distinct from new.pallets then
        perform plan_h_bridge_recut(v_sh, 'trigger:plan_bridge_sync', 'trigger:plan_bridge_sync', 'system');
      end if;
      select * into v_o from orders where id = new.order_id;
      if old.datetime is distinct from new.datetime and current_setting('plan.writer', true) is distinct from 'natl'
         and plan_h_vs_nat_side(v_o.direction, new.stop_type) then
        perform plan_h_bridge_unplan(new.order_id, new.id, 'trigger:plan_bridge_sync', 'trigger:plan_bridge_sync', 'system');
      end if;
    end if;
    if old.order_id is not null and old.order_id is distinct from new.order_id then
      perform plan_bridge_sync(old.order_id, 'trigger:plan_bridge_sync');
    end if;
  end if;
  if new.order_id is not null then perform plan_bridge_sync(new.order_id, 'trigger:plan_bridge_sync'); end if;
  return null;
end
$f$;
  CREATE OR REPLACE FUNCTION public.pl_h_delivery_write(p_order bigint, p_stop bigint, p_why text) RETURNS int
    LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $f$
  DECLARE
    v_o orders%ROWTYPE; v_s record; v_day date; v_new pl_movements%ROWTYPE; v_n int := 0;
  BEGIN
    SELECT * INTO v_o FROM orders WHERE id = p_order;
    IF NOT FOUND OR v_o.deleted_at IS NOT NULL OR v_o.status IS DISTINCT FROM 'Delivered' OR v_o.pallet_exchange IS NOT TRUE THEN
      RETURN 0;
    END IF;
    -- the browser feeder's exceptions (core/pallet-feed.js plOrderGate)
    IF v_o.parent_order_id IS NOT NULL THEN RETURN 0; END IF;
    IF EXISTS (SELECT 1 FROM stock_lots WHERE order_id = p_order AND deleted_at IS NULL) THEN RETURN 0; END IF;
    -- no client = no counterparty (one_counterparty CHECK): skipped, never a failed save; the stop stays in
    -- pl_v_missing_delivery, where the accountant and the auditor see it
    IF v_o.client_id IS NULL THEN RETURN 0; END IF;
    v_day := (now() AT TIME ZONE 'Europe/Athens')::date;
    -- 111: the pallets with exchange of the stop (the form's tick, owner 8/11): NULL = every pallet, as before; a whole
    -- number 1..pallets = that many; any other value is never trusted (all pallets, and the value goes in the trace)
    FOR v_s IN SELECT id, location_id, round(pallets)::int AS pallets, datetime, pallets_exchanged AS ex,
                      CASE WHEN pallets_exchanged = trunc(pallets_exchanged) AND pallets_exchanged >= 1
                                AND pallets_exchanged <= round(pallets) THEN pallets_exchanged::int
                           ELSE round(pallets)::int END AS exch
                 FROM order_stops
                -- whole pallets as 107's list shows them (round): a stop the list calls "0 pal." is not written
                WHERE order_id = p_order AND stop_type = 'Unloading' AND deleted_at IS NULL AND round(coalesce(pallets, 0)) >= 1
                  AND (p_stop IS NULL OR id = p_stop)
                  -- 111: a stop the form says has no exchange (0) gets no delivery movement
                  AND pallets_exchanged IS DISTINCT FROM 0
                ORDER BY id LOOP
      v_new := NULL;
      INSERT INTO pl_movements (movement_date, counterparty_type, client_id, location_id, event_type, taken, given,
                                order_stop_id, order_id, status, created_by, confirmed_by, confirmed_at)
      VALUES (CASE WHEN p_why = 'status' THEN v_day ELSE coalesce(v_o.actual_delivery_date, v_s.datetime, v_day) END,
              'CLIENT', v_o.client_id, v_s.location_id, 'DELIVERY', v_s.exch, v_s.exch,
              v_s.id, p_order, 'confirmed', 'system', 'system', now())
      ON CONFLICT (order_stop_id, event_type)
        WHERE order_stop_id IS NOT NULL AND status <> 'reversed' AND event_type = ANY (ARRAY['LOADING'::text, 'DELIVERY'::text])
        DO NOTHING
      RETURNING * INTO v_new;
      IF v_new.id IS NOT NULL THEN
        PERFORM plan_h_audit('system', 'system', 'create', 'pl_movements', v_new.id::text, NULL,
          to_jsonb(v_new) || jsonb_build_object('source', 'trigger:108', 'why', p_why, 'stop_exchanged', v_s.ex));
        v_n := v_n + 1;
      END IF;
    END LOOP;
    RETURN v_n;
  END $f$;
  DROP TRIGGER plan_bridge_on_stop ON public.order_stops;
  CREATE TRIGGER plan_bridge_on_stop AFTER INSERT OR UPDATE OF location_id, pallets, deleted_at, stop_type, datetime, order_id, via_hub
    ON public.order_stops FOR EACH ROW EXECUTE FUNCTION public.plan_bridge_on_stop();
  UPDATE monitoring.checks SET sql_text = 'SELECT count(*) FROM orders o WHERE EXISTS (SELECT 1 FROM order_stops s WHERE s.order_id = o.id AND ((o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM ''Cancelled'' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND s.via_hub IS DISTINCT FROM false AND coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false) AND EXISTS (SELECT 1 FROM plan_config c WHERE coalesce(o.cross_dock_date >= c.cutover_day, false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM ''074 rollback''))) <> EXISTS (SELECT 1 FROM shipments b WHERE b.order_stop_id = s.id AND b.deleted_at IS NULL)))',
         ids_sql = 'SELECT coalesce(array_agg(x ORDER BY x), ''{}'') FROM (SELECT coalesce(o.legacy_id, o.id::text) AS x FROM orders o WHERE EXISTS (SELECT 1 FROM order_stops s WHERE s.order_id = o.id AND ((o.deleted_at IS NULL AND coalesce(o.veroia_switch, false) AND o.status IS DISTINCT FROM ''Cancelled'' AND s.deleted_at IS NULL AND coalesce(s.pallets, 0) > 0 AND s.via_hub IS DISTINCT FROM false AND coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false) AND EXISTS (SELECT 1 FROM plan_config c WHERE coalesce(o.cross_dock_date >= c.cutover_day, false) OR EXISTS (SELECT 1 FROM shipments b0 WHERE b0.order_id = o.id AND b0.order_stop_id IS NOT NULL AND b0.deleted_reason IS DISTINCT FROM ''074 rollback''))) <> EXISTS (SELECT 1 FROM shipments b WHERE b.order_stop_id = s.id AND b.deleted_at IS NULL))) ORDER BY 1 LIMIT 50) s',
         exceptions = convert_from(decode('', 'base64'), 'UTF8')
   WHERE id = 'B-95';
  UPDATE monitoring.checks SET sql_text = 'SELECT count(*) FROM order_stops s JOIN orders o ON o.id = s.order_id WHERE s.via_hub IS NOT NULL AND NOT coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false)',
         ids_sql = 'SELECT coalesce(array_agg(x ORDER BY x), ''{}'') FROM (SELECT coalesce(s.legacy_id, s.id::text) AS x FROM order_stops s JOIN orders o ON o.id = s.order_id WHERE s.via_hub IS NOT NULL AND NOT coalesce((o.direction = ''Import'' AND s.stop_type = ''Unloading'') OR (o.direction = ''Export'' AND s.stop_type = ''Loading''), false) ORDER BY 1 LIMIT 50) s',
         title = convert_from(decode('wqvOnM6tz4PPiSDOks6tz4HOv865zrHPgsK7IM+DzrUgz4PPhM6sz4POtyDPgM6/z4UgzrTOtc69IM61zq/Ovc6xzrkgzrXOuM69zrnOus6uIM+AzrvOtc+Fz4HOrA==', 'base64'), 'UTF8'),
         impact = convert_from(decode('', 'base64'), 'UTF8'),
         next_step = convert_from(decode('T3duZXI6IM+Azr/Ouc6xIM60zrnOsc60z4HOv868zq4gz4TOvyDOrc6zz4HOsc+IzrUgKM63IM+Gz4zPgc68zrEgz4TOvyDPg8+Ezq3Ou869zrXOuSDOvM+Mzr3OvyDPg8+EzrnPgiDPg8+EzqzPg861zrnPgiDOtc64zr3Ouc66zq7PgiDPgM67zrXPhc+BzqzPgiku', 'base64'), 'UTF8'),
         exceptions = convert_from(decode('', 'base64'), 'UTF8')
   WHERE id = 'B-99';

  -- ===== PART 3 (c): THE DELIVERY FOLLOWS THE STOP'S EXCHANGE =====
  -- pl_h_delivery_write is above (with the bridge bodies); the list of 107 follows the same rule
  CREATE OR REPLACE VIEW public.pl_v_missing_delivery WITH (security_invoker = true) AS
  SELECT s.id AS order_stop_id, o.id AS order_id, o.direction,
         o.client_id, c.company_name AS client_name,
         s.location_id, l.name AS location_name, l.city AS location_city, l.country AS location_country,
         round(s.pallets)::int AS pallets, s.datetime AS stop_date, o.delivery_datetime, o.actual_delivery_date,
         coalesce(o.actual_delivery_date, s.datetime, o.delivery_datetime) AS delivered_on,
         (SELECT count(*) FROM public.order_stops u
           WHERE u.order_id = o.id AND u.stop_type = 'Unloading' AND u.deleted_at IS NULL AND coalesce(u.pallets, 0) > 0)::int AS unloading_stops,
         EXISTS (SELECT 1 FROM public.shipments sh WHERE sh.order_id = o.id AND sh.deleted_at IS NULL) AS has_nat_leg
    FROM public.orders o
    JOIN public.order_stops s ON s.order_id = o.id AND s.deleted_at IS NULL AND s.stop_type = 'Unloading' AND coalesce(s.pallets, 0) > 0
                             AND s.pallets_exchanged IS DISTINCT FROM 0   -- 111: no exchange at this stop = nothing missing
    LEFT JOIN public.clients c ON c.id = o.client_id
    LEFT JOIN public.locations l ON l.id = s.location_id
   WHERE o.deleted_at IS NULL AND o.status = 'Delivered' AND o.pallet_exchange IS TRUE AND o.parent_order_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM public.stock_lots sl WHERE sl.order_id = o.id AND sl.deleted_at IS NULL)
     AND NOT EXISTS (SELECT 1 FROM public.pl_movements m
                      WHERE m.order_stop_id = s.id AND m.event_type = 'DELIVERY' AND m.status <> 'reversed');
  REVOKE ALL ON public.pl_v_missing_delivery FROM PUBLIC, anon, authenticated;
  GRANT SELECT ON public.pl_v_missing_delivery TO service_role, tms_check_runner;

  -- ===== PART 4: CLOSED, AND THE PROOFS =====
  -- CREATE OR REPLACE keeps each function's grants (074 / 108 left them closed); said again, born closed (principle 5)
  REVOKE ALL ON FUNCTION public.plan_h_bridge_wanted(bigint) FROM PUBLIC, anon, authenticated;
  REVOKE ALL ON FUNCTION public.plan_bridge_sync(bigint, text) FROM PUBLIC, anon, authenticated;
  REVOKE ALL ON FUNCTION public.plan_bridge_on_stop() FROM PUBLIC, anon, authenticated;
  REVOKE ALL ON FUNCTION public.pl_h_delivery_write(bigint, bigint, text) FROM PUBLIC, anon, authenticated;
  EXECUTE (SELECT sql_text FROM monitoring.checks WHERE id = 'B-95') INTO v_b95;
  EXECUTE (SELECT sql_text FROM monitoring.checks WHERE id = 'B-99') INTO v_b99;
  SELECT count(*) INTO v_sh1 FROM public.shipments WHERE deleted_at IS NULL;
  SELECT count(*) INTO v_trg1 FROM pg_trigger t JOIN pg_class c ON c.oid = t.tgrelid JOIN pg_namespace ns ON ns.oid = c.relnamespace
   WHERE NOT t.tgisinternal AND t.tgenabled <> 'D' AND ns.nspname = 'public';
  IF v_b95 <> 0 OR v_b99 <> 0 OR v_sh1 <> v_sh0 OR v_trg1 <> v_trg0 THEN
    RAISE EXCEPTION '111: after - B-95 %, B-99 %, live shipments % -> %, triggers % -> % (expected 0, 0, equal, equal)', v_b95, v_b99, v_sh0, v_sh1, v_trg0, v_trg1;
  END IF;

  RAISE NOTICE '111 OK: time_from / time_to added; via_hub = the desk''s choice (% true + % false echoes -> NULL); bridge, B-95 / B-99, delivery and its list follow; B-95 %, B-99 %, live shipments % = %; % ms',
    v_true0, v_false0, v_b95, v_b99, v_sh0, v_sh1, round(extract(epoch FROM clock_timestamp() - v_t0) * 1000);
END
$do$;
